-- Shared catalog, campaigns, storefront settings and coupons.
-- Run after supabase-auth.sql in the Supabase SQL editor.
BEGIN;

CREATE TABLE IF NOT EXISTS public.catalog_products (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  seller TEXT NOT NULL,
  price NUMERIC(12,2) NOT NULL CHECK (price >= 0),
  old_price NUMERIC(12,2),
  stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
  rating NUMERIC(3,2) NOT NULL DEFAULT 0,
  reviews INTEGER NOT NULL DEFAULT 0,
  description TEXT NOT NULL DEFAULT '',
  photos JSONB NOT NULL CONSTRAINT catalog_products_exactly_three_images CHECK (jsonb_typeof(photos) = 'array' AND jsonb_array_length(photos) = 3),
  attributes JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(attributes) = 'object'),
  product_data JSONB NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(product_data) = 'object'),
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.ad_campaigns (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_key TEXT,
  name TEXT NOT NULL,
  headline TEXT NOT NULL,
  message TEXT NOT NULL DEFAULT '',
  cta_text TEXT NOT NULL DEFAULT 'Shop now',
  destination_url TEXT NOT NULL DEFAULT '/shop',
  image_url TEXT,
  youtube_url TEXT,
  placement TEXT NOT NULL CHECK (placement IN ('global','side_left','side_right','after_departments','after_popular','product_grid','product_detail','video_home','video_product')),
  active BOOLEAN NOT NULL DEFAULT TRUE,
  display_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Align an existing ad_campaigns table created by database/schema.sql.
ALTER TABLE public.ad_campaigns ADD COLUMN IF NOT EXISTS source_key TEXT;
ALTER TABLE public.ad_campaigns ADD COLUMN IF NOT EXISTS cta_text TEXT NOT NULL DEFAULT 'Shop now';
ALTER TABLE public.ad_campaigns ADD COLUMN IF NOT EXISTS destination_url TEXT NOT NULL DEFAULT '/shop';
ALTER TABLE public.ad_campaigns ADD COLUMN IF NOT EXISTS youtube_url TEXT;

CREATE TABLE IF NOT EXISTS public.storefront_settings (
  setting_key TEXT PRIMARY KEY,
  setting_value JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.store_coupons (
  code TEXT PRIMARY KEY CHECK (code = upper(code)),
  discount_type TEXT NOT NULL CHECK (discount_type IN ('percent','fixed','free-shipping')),
  discount_value NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (discount_value >= 0),
  minimum NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (minimum >= 0),
  maximum NUMERIC(12,2),
  description TEXT NOT NULL DEFAULT '',
  categories JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(categories) = 'array'),
  expires_at DATE,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS catalog_products_active_category_idx ON public.catalog_products(category, slug) WHERE active;
CREATE INDEX IF NOT EXISTS ad_campaigns_active_placement_order_idx ON public.ad_campaigns(placement, display_order) WHERE active;
CREATE UNIQUE INDEX IF NOT EXISTS ad_campaigns_source_key_uidx ON public.ad_campaigns(source_key);

ALTER TABLE public.catalog_products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ad_campaigns ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.storefront_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.store_coupons ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.catalog_products, public.ad_campaigns, public.storefront_settings, public.store_coupons FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.catalog_products, public.ad_campaigns, public.storefront_settings TO anon, authenticated;
GRANT SELECT ON public.store_coupons TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.catalog_products, public.ad_campaigns, public.storefront_settings, public.store_coupons TO authenticated;

DROP POLICY IF EXISTS "Public reads active products" ON public.catalog_products;
CREATE POLICY "Public reads active products" ON public.catalog_products FOR SELECT TO anon, authenticated USING (active);
DROP POLICY IF EXISTS "Super admins read all products" ON public.catalog_products;
CREATE POLICY "Super admins read all products" ON public.catalog_products FOR SELECT TO authenticated USING ((SELECT private.current_user_is_super_admin()));
DROP POLICY IF EXISTS "Super admins manage products" ON public.catalog_products;
CREATE POLICY "Super admins manage products" ON public.catalog_products FOR ALL TO authenticated USING ((SELECT private.current_user_is_super_admin())) WITH CHECK ((SELECT private.current_user_is_super_admin()));

DROP POLICY IF EXISTS "Public reads active campaigns" ON public.ad_campaigns;
CREATE POLICY "Public reads active campaigns" ON public.ad_campaigns FOR SELECT TO anon, authenticated USING (active);
DROP POLICY IF EXISTS "Super admins read all campaigns" ON public.ad_campaigns;
CREATE POLICY "Super admins read all campaigns" ON public.ad_campaigns FOR SELECT TO authenticated USING ((SELECT private.current_user_is_super_admin()));
DROP POLICY IF EXISTS "Super admins manage campaigns" ON public.ad_campaigns;
CREATE POLICY "Super admins manage campaigns" ON public.ad_campaigns FOR ALL TO authenticated USING ((SELECT private.current_user_is_super_admin())) WITH CHECK ((SELECT private.current_user_is_super_admin()));

DROP POLICY IF EXISTS "Public reads storefront settings" ON public.storefront_settings;
CREATE POLICY "Public reads storefront settings" ON public.storefront_settings FOR SELECT TO anon, authenticated USING (TRUE);
DROP POLICY IF EXISTS "Super admins manage storefront settings" ON public.storefront_settings;
CREATE POLICY "Super admins manage storefront settings" ON public.storefront_settings FOR ALL TO authenticated USING ((SELECT private.current_user_is_super_admin())) WITH CHECK ((SELECT private.current_user_is_super_admin()));

DROP POLICY IF EXISTS "Public reads active coupons" ON public.store_coupons;
CREATE POLICY "Public reads active coupons" ON public.store_coupons FOR SELECT TO anon, authenticated USING (active);
DROP POLICY IF EXISTS "Super admins read all coupons" ON public.store_coupons;
CREATE POLICY "Super admins read all coupons" ON public.store_coupons FOR SELECT TO authenticated USING ((SELECT private.current_user_is_super_admin()));
DROP POLICY IF EXISTS "Super admins manage coupons" ON public.store_coupons;
CREATE POLICY "Super admins manage coupons" ON public.store_coupons FOR ALL TO authenticated USING ((SELECT private.current_user_is_super_admin())) WITH CHECK ((SELECT private.current_user_is_super_admin()));

-- Campaign images and product photos are binary objects in Supabase Storage;
-- the tables above hold their public URLs and campaign/product metadata.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('marketplace-media', 'marketplace-media', TRUE, 8388608, ARRAY['image/jpeg','image/png','image/webp','image/gif']::text[])
ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;

DROP POLICY IF EXISTS "Public reads marketplace media" ON storage.objects;
CREATE POLICY "Public reads marketplace media" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'marketplace-media');
DROP POLICY IF EXISTS "Super admins upload marketplace media" ON storage.objects;
CREATE POLICY "Super admins upload marketplace media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'marketplace-media' AND (SELECT private.current_user_is_super_admin()));
DROP POLICY IF EXISTS "Super admins update marketplace media" ON storage.objects;
CREATE POLICY "Super admins update marketplace media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'marketplace-media' AND (SELECT private.current_user_is_super_admin())) WITH CHECK (bucket_id = 'marketplace-media' AND (SELECT private.current_user_is_super_admin()));
DROP POLICY IF EXISTS "Super admins delete marketplace media" ON storage.objects;
CREATE POLICY "Super admins delete marketplace media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'marketplace-media' AND (SELECT private.current_user_is_super_admin()));

